    void comprobar(String ruta, int esperado) throws Exception {
        var request = HttpRequest.newBuilder(URI.create("http://localhost:" + port + ruta)).GET().build();
        var response = client.send(request, HttpResponse.BodyHandlers.ofString());
        assertEquals(esperado, response.statusCode(), ruta + " " + response.body());
        assertTrue(response.headers().firstValue("content-type").orElse("").contains("json"));
        if (esperado == 200) {
            assertFalse(response.body().isBlank());
            if (ruta.matches("/api/[^/]+")) {
                assertTrue(response.body().startsWith("["));
                assertFalse(response.body().equals("[]"));
            } else assertTrue(response.body().startsWith("{"));
            assertFalse(response.body().contains("clausu"), "La respuesta no debe exponer claves");
        }
    }
